     &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;boutonCombat&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;Combat&#39;);&quot; onmouseout=&quot;outButton(&#39;Combat&#39;);&quot; onclick=&quot;expandMenu(&#39;Combat&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html&quot; title=&quot;Le combat de masse&quot;&gt;Le combat de masse&lt;/a&gt;
